trait Loggable {
    fn log_message(&self) -> String;
}
trait Audit: Loggable {
    fn audit_code(&self) -> u32;
}
struct Event { id: u32 }

⟦impl_loggable_slot⟧

impl Audit for Event {
    fn audit_code(&self) -> u32 { self.id }
}
fn process<T: Audit>(item: &T) -> String {
    format!("[{}] {}", item.audit_code(), item.⟦call_log_slot⟧)
}
fn main() {
    let e = Event { id: 101 };
    println!("{}", process(&e));
}

